# output likely overlay blocks with precedence 9 then 4 then 8 then 5? Demo: at coordinate all pixels, out values in order priority. derive priority compare ambiguous positions; enumerate global priority scoring
D=[[[8,8,8,0,3,5,5,5,0,3,9,9,9,0,3,4,4,4,4],[8,0,8,0,3,5,5,5,5,3,9,9,0,9,3,0,0,0,0],[0,0,0,8,3,5,5,0,0,3,0,0,0,0,3,0,4,4,0],[0,8,0,0,3,0,5,5,5,3,9,0,0,0,3,4,4,4,4]],[[0,0,8,8,3,5,5,0,0,3,0,9,9,9,3,4,0,4,0],[8,8,8,8,3,0,5,0,5,3,0,9,0,9,3,4,0,4,0],[8,8,0,8,3,5,0,5,5,3,0,0,0,9,3,0,4,0,4],[0,8,8,0,3,0,0,0,5,3,9,0,0,9,3,0,0,0,0]]]; O=[[[9,9,9,4],[9,9,8,9],[5,4,4,8],[9,4,4,4]],[[4,9,9,9],[4,9,4,9],[8,4,5,9],[9,8,8,9]]]
import itertools
for p in itertools.permutations([8,5,9,4]):
 ok=0; total=0
 for d,o in zip(D,O):
  B=[[[d[r][s+c] for c in range(4)] for r in range(4)] for s in (0,5,10,15)]
  for r in range(4):
   for c in range(4):
    vals=[b[r][c] for b in B if b[r][c]]; pred=next((v for v in p if v in vals),0); total+=1;ok+=pred==o[r][c]
 if ok==total:print('priority',p)
